"use client";

import "./competition-discovery.css";
import "./event-timeline.css";
import "./event-planner.css";
import "./event-archive.css";

import {Fragment,useEffect,useMemo,useState} from "react";
import {catalogueSources,catalogueVerifiedAt,eventCatalogue,EventRecord} from "./event-catalogue";
import {eventContinent,eventContinents,eventCountries} from "./event-geography";
import {ClubAthlete,defaultClubAthletes,readClubAthletes} from "./club-data";
import {eventTeamLinksKey,EventTeamLinks,EventTeamOperation,EventTeamOperations,readEventTeamLinks,readEventTeamOperations} from "./event-club-links";
import {defaultOrganisationBrand,OrganisationBrand,OrganisationMark,readOrganisationBrand} from "./organisation-brand";

type Period="Current events"|"Past events";
type Layout="Timeline"|"Agenda"|"Cards";
type IntegrityFilter="All events"|"Dates to review"|"Missing results";
type ResultFilter="All results"|"Complete"|"Partial"|"Missing";
type CurrentFilter="All current"|"Live now"|"Registration open"|"Closing soon"|"Upcoming"|"Dates to review";
type DateRange="All time"|"30 days"|"90 days"|"12 months";
type EventView="All events"|"My events"|"Needs action";
type Decision="Watching"|"Considering"|"Entering"|"Not attending";
type EventPlan={decision:Decision;athletes:string[];travel:string;hotel:string;budget:string;notes:string;checks:string[]};
type Plans=Record<string,EventPlan>;

const emptyPlan:EventPlan={decision:"Watching",athletes:[],travel:"",hotel:"",budget:"",notes:"",checks:[]};
const registrationChecks=[{id:"licences",label:"Licences checked",detail:"All competitor licences are valid on the event date"},{id:"categories",label:"Categories confirmed",detail:"Age, weight and disciplines match the organiser listing"},{id:"consent",label:"Consent confirmed",detail:"Parent or athlete permissions are recorded"},{id:"payment",label:"Fees approved",detail:"Entry costs and payment responsibility are agreed"}];
const ukCalendarDate=()=>{const parts=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/London",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const part=(type:Intl.DateTimeFormatPartTypes)=>parts.find(item=>item.type===type)?.value??"";return `${part("year")}-${part("month")}-${part("day")}`};
const readList=(key:string)=>{if(typeof window==="undefined")return[] as string[];try{const value=JSON.parse(localStorage.getItem(key)||"[]");return Array.isArray(value)?value.filter(item=>typeof item==="string"):[]}catch{return[]}};
const readPlans=()=>{if(typeof window==="undefined")return{} as Plans;try{const value=JSON.parse(localStorage.getItem("fighteye-event-plans-v2")||"{}");return value&&typeof value==="object"?value as Plans:{}}catch{return{}}};
const dateLabel=(start:string,end:string)=>{const format=(value:string)=>new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`));return start===end?format(start):`${format(start)} – ${format(end)}`};
const monthLabel=(value:string)=>new Intl.DateTimeFormat("en-GB",{month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`));
const dateParts=(value:string)=>{const date=new Date(`${value}T12:00:00Z`);return{day:new Intl.DateTimeFormat("en-GB",{day:"2-digit",timeZone:"UTC"}).format(date),month:new Intl.DateTimeFormat("en-GB",{month:"short",timeZone:"UTC"}).format(date),weekday:new Intl.DateTimeFormat("en-GB",{weekday:"short",timeZone:"UTC"}).format(date)}};
const eventState=(event:EventRecord,today:string)=>event.end<today?"Completed":event.start<=today?"Live":event.closing&&event.closing<today?"Registration closed":event.closing&&event.closing>=today?"Registration open":"Upcoming";
const daysUntil=(date:string,today:string)=>Math.ceil((new Date(`${date}T12:00:00Z`).getTime()-new Date(`${today}T12:00:00Z`).getTime())/86400000);
const shiftDate=(value:string,days:number)=>{const date=new Date(`${value}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)};
const eventsOverlap=(a:Pick<EventRecord,"start"|"end">,b:Pick<EventRecord,"start"|"end">)=>a.start<=b.end&&b.start<=a.end;
const directionsUrl=(event:EventRecord)=>`https://maps.apple.com/?q=${encodeURIComponent(`${event.venue}, ${event.city}, ${event.country}`)}`;
const escapeCalendar=(value:string)=>value.replaceAll("\\","\\\\").replaceAll(";","\\;").replaceAll(",","\\,").replaceAll("\n","\\n");
const calendarContent=(events:EventRecord[])=>{const compact=(value:string)=>value.replaceAll("-","");const lines=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//FightEye//Event Timeline//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH","X-WR-CALNAME:FightEye events"];events.forEach(event=>{const next=new Date(`${event.end}T12:00:00Z`);next.setUTCDate(next.getUTCDate()+1);lines.push("BEGIN:VEVENT",`UID:${event.id}@fighteye`,`DTSTART;VALUE=DATE:${compact(event.start)}`,`DTEND;VALUE=DATE:${compact(next.toISOString().slice(0,10))}`,`SUMMARY:${escapeCalendar(event.name)}`,`LOCATION:${escapeCalendar(`${event.venue}, ${event.city}, ${event.country}`)}`,`DESCRIPTION:${escapeCalendar(`${event.org}. Registration: ${event.registrationUrl}`)}`,`URL:${event.registrationUrl}`,"END:VEVENT")});return[...lines,"END:VCALENDAR"].join("\r\n")};
const dateStatus=(event:EventRecord)=>event.dateStatus??(event.verified&&!["Sportdata","Kihapp"].includes(event.sourceName)?"Verified":"Provisional");
const resultStatus=(event:EventRecord,today:string)=>event.end>=today?"Not due":event.resultStatus??"Missing";
const statusClass=(value:string)=>value.toLowerCase().replaceAll(" ","-");
export const eventBelongsInPast=(event:Pick<EventRecord,"end">,today:string)=>event.end<today;
export const eventBelongsInCurrent=(event:Pick<EventRecord,"end">,today:string)=>event.end>=today;
export const eventIsLive=(event:Pick<EventRecord,"start"|"end">,today:string)=>event.start<=today&&event.end>=today;

export default function CompetitionDiscovery({notice,openLiveEvent}:{notice:(message:string)=>void;openLiveEvent:(event:EventRecord)=>void}){
 const today=ukCalendarDate();
 const[query,setQuery]=useState("");
 const[org,setOrg]=useState("All organisers");
 const[level,setLevel]=useState("All levels");
 const[continent,setContinent]=useState("All continents");
 const[country,setCountry]=useState("All countries");
 const[month,setMonth]=useState("All dates");
 const[period,setPeriod]=useState<Period>("Current events");
 const[currentFilter,setCurrentFilter]=useState<CurrentFilter>("All current");
 const[dateRange,setDateRange]=useState<DateRange>("All time");
 const[eventView,setEventView]=useState<EventView>("All events");
 const[layout,setLayout]=useState<Layout>("Timeline");
 const[trackedOnly,setTrackedOnly]=useState(false);
 const[clubOnly,setClubOnly]=useState(false);
 const[integrityFilter,setIntegrityFilter]=useState<IntegrityFilter>("All events");
 const[resultFilter,setResultFilter]=useState<ResultFilter>("All results");
 const[pastYear,setPastYear]=useState("All years");
 const[tracked,setTracked]=useState<string[]>([]);
 const[plans,setPlans]=useState<Plans>({});
 const[teamLinks,setTeamLinks]=useState<EventTeamLinks>({});
 const[teamOperations,setTeamOperations]=useState<EventTeamOperations>({});
 const[selected,setSelected]=useState<EventRecord|null>(null);
 const[detailTab,setDetailTab]=useState<"Overview"|"Club plan"|"Entries">("Overview");
 const[compareIds,setCompareIds]=useState<string[]>([]);
 const[clubAthletes,setClubAthletes]=useState(()=>defaultClubAthletes.filter(athlete=>athlete.membership!=="Paused"));
 const[organisation,setOrganisation]=useState<OrganisationBrand>(defaultOrganisationBrand);
 const[deviceStateReady,setDeviceStateReady]=useState(false);
 const[filtersOpen,setFiltersOpen]=useState(false);
 const[visibleLimit,setVisibleLimit]=useState(12);
 const[geographyReady,setGeographyReady]=useState(false);

 useEffect(()=>{try{const value=JSON.parse(localStorage.getItem("fighteye-event-geography-v1")||"{}");const savedContinent=typeof value.continent==="string"&&eventContinents(eventCatalogue).includes(value.continent)?value.continent:"All continents";setContinent(savedContinent);if(typeof value.country==="string"&&eventCountries(eventCatalogue,savedContinent).includes(value.country))setCountry(value.country)}catch{}setGeographyReady(true)},[]);
 useEffect(()=>{if(!geographyReady)return;try{localStorage.setItem("fighteye-event-geography-v1",JSON.stringify({continent,country}))}catch{}},[geographyReady,continent,country]);

 useEffect(()=>{const frame=requestAnimationFrame(()=>{setTracked(readList("fighteye-tracked-events"));setPlans(readPlans());setTeamLinks(readEventTeamLinks());setTeamOperations(readEventTeamOperations());setClubAthletes(readClubAthletes().filter(athlete=>athlete.membership!=="Paused"));setOrganisation(readOrganisationBrand());setDeviceStateReady(true)});return()=>cancelAnimationFrame(frame)},[]);
 useEffect(()=>{if(!deviceStateReady)return;const timer=setTimeout(()=>{try{localStorage.setItem("fighteye-tracked-events",JSON.stringify(tracked))}catch{}},160);return()=>clearTimeout(timer)},[deviceStateReady,tracked]);
 useEffect(()=>{if(!deviceStateReady)return;const timer=setTimeout(()=>{try{localStorage.setItem("fighteye-event-plans-v2",JSON.stringify(plans))}catch{}},160);return()=>clearTimeout(timer)},[deviceStateReady,plans]);
 useEffect(()=>{if(!deviceStateReady)return;const timer=setTimeout(()=>{try{localStorage.setItem(eventTeamLinksKey,JSON.stringify(teamLinks))}catch{}},160);return()=>clearTimeout(timer)},[deviceStateReady,teamLinks]);
 useEffect(()=>{if(!selected)return;const close=(event:KeyboardEvent)=>{if(event.key==="Escape")setSelected(null)};window.addEventListener("keydown",close);return()=>window.removeEventListener("keydown",close)},[selected]);
 useEffect(()=>{const timer=setTimeout(()=>setVisibleLimit(12),0);return()=>clearTimeout(timer)},[query,org,level,continent,country,month,period,currentFilter,dateRange,eventView,trackedOnly,clubOnly,integrityFilter,resultFilter,pastYear,layout]);

 const organisers=["All organisers",...Array.from(new Set(eventCatalogue.map(event=>event.org))).sort()];
 const continents=eventContinents(eventCatalogue);
 const countries=eventCountries(eventCatalogue,continent);
 const months=["All dates",...Array.from(new Set(eventCatalogue.filter(event=>event.end>=today).map(event=>monthLabel(event.start))))];
 const activeIntegrityFilter=period==="Current events"&&integrityFilter==="Missing results"?"All events":integrityFilter;
 const periodFiltered=useMemo(()=>eventCatalogue.filter(event=>period==="Past events"?eventBelongsInPast(event,today):eventBelongsInCurrent(event,today)).filter(event=>period==="Past events"||currentFilter==="All current"||(currentFilter==="Live now"?eventIsLive(event,today):currentFilter==="Registration open"?eventState(event,today)==="Registration open":currentFilter==="Closing soon"?Boolean(event.closing&&daysUntil(event.closing,today)>=0&&daysUntil(event.closing,today)<=14):currentFilter==="Upcoming"?event.start>today:dateStatus(event)==="Provisional")).filter(event=>activeIntegrityFilter==="All events"||(activeIntegrityFilter==="Dates to review"?dateStatus(event)==="Provisional":resultStatus(event,today)==="Missing"||resultStatus(event,today)==="Partial")).filter(event=>continent==="All continents"||eventContinent(event)===continent).filter(event=>country==="All countries"||event.country===country).filter(event=>org==="All organisers"||event.org===org).filter(event=>level==="All levels"||event.level===level).filter(event=>!trackedOnly||tracked.includes(event.id)).filter(event=>!clubOnly||(teamLinks[event.id]?.athleteIds.length??plans[event.id]?.athletes.length??0)>0).filter(event=>`${event.name} ${event.org} ${event.city} ${event.country} ${event.disciplines.join(" ")} ${event.collections.join(" ")} ${event.sourceName}`.toLowerCase().includes(query.trim().toLowerCase())).sort((a,b)=>period==="Past events"?b.end.localeCompare(a.end):eventIsLive(a,today)&&!eventIsLive(b,today)?-1:!eventIsLive(a,today)&&eventIsLive(b,today)?1:a.start.localeCompare(b.start)),[period,currentFilter,activeIntegrityFilter,continent,country,org,level,trackedOnly,tracked,clubOnly,teamLinks,plans,query,today]);
 const rangeFiltered=useMemo(()=>{if(dateRange==="All time")return periodFiltered;const days=dateRange==="30 days"?30:dateRange==="90 days"?90:365;return periodFiltered.filter(event=>period==="Current events"?eventIsLive(event,today)||event.start<=shiftDate(today,days):event.end>=shiftDate(today,-days))},[periodFiltered,period,dateRange,today]);
 const isMyEvent=(event:EventRecord)=>tracked.includes(event.id)||Boolean(teamLinks[event.id]?.athleteIds.length)||["Considering","Entering"].includes(plans[event.id]?.decision??"");
 const needsAction=(event:EventRecord)=>{const plan=plans[event.id];const linked=teamLinks[event.id]?.athleteIds.length??plan?.athletes.length??0;const deadline=event.closing?daysUntil(event.closing,today):null;return isMyEvent(event)&&(dateStatus(event)==="Provisional"||(deadline!==null&&deadline>=0&&deadline<=14&&(plan?.checks.length??0)<registrationChecks.length)||(linked>0&&(teamOperations[event.id]?.coachIds.length??0)===0))};
 const focusedEvents=useMemo(()=>rangeFiltered.filter(event=>{const mine=tracked.includes(event.id)||Boolean(teamLinks[event.id]?.athleteIds.length)||["Considering","Entering"].includes(plans[event.id]?.decision??"");if(eventView==="All events")return true;if(eventView==="My events")return mine;const plan=plans[event.id];const linked=teamLinks[event.id]?.athleteIds.length??plan?.athletes.length??0;const deadline=event.closing?daysUntil(event.closing,today):null;return mine&&(dateStatus(event)==="Provisional"||(deadline!==null&&deadline>=0&&deadline<=14&&(plan?.checks.length??0)<registrationChecks.length)||(linked>0&&(teamOperations[event.id]?.coachIds.length??0)===0))}),[rangeFiltered,eventView,tracked,teamLinks,plans,teamOperations,today]);
 const visible=useMemo(()=>focusedEvents.filter(event=>period==="Current events"?(month==="All dates"||monthLabel(event.start)===month):(pastYear==="All years"||event.end.startsWith(pastYear))&&(resultFilter==="All results"||resultStatus(event,today)===resultFilter)),[focusedEvents,period,month,pastYear,resultFilter,today]);
 const {timelineMonths,timelineMonthCounts}=useMemo(()=>{const counts:Record<string,number>={};for(const event of focusedEvents){const label=monthLabel(event.start);counts[label]=(counts[label]??0)+1}return{timelineMonths:Object.keys(counts),timelineMonthCounts:counts}},[focusedEvents]);
 const clashesByEvent=useMemo(()=>{const byEvent:Record<string,string[]>={};visible.forEach(event=>{byEvent[event.id]=[]});visible.forEach((event,index)=>visible.slice(index+1).forEach(other=>{if(!eventsOverlap(event,other))return;byEvent[event.id].push(other.name);byEvent[other.id].push(event.name)}));return byEvent},[visible]);
 const displayedEvents=visible.slice(0,visibleLimit);
 const currentEvents=eventCatalogue.filter(event=>eventBelongsInCurrent(event,today));
 const liveEvents=currentEvents.filter(event=>eventIsLive(event,today));
 const registrationOpenEvents=currentEvents.filter(event=>eventState(event,today)==="Registration open");
 const deadlineEvents=currentEvents.filter(event=>event.closing&&event.closing>=today).sort((a,b)=>(a.closing??"").localeCompare(b.closing??""));
 const closingSoonEvents=deadlineEvents.filter(event=>daysUntil(event.closing!,today)<=14);
 const futureEvents=currentEvents.filter(event=>event.start>today);
 const primaryEvent=liveEvents[0]??[...futureEvents].sort((a,b)=>a.start.localeCompare(b.start))[0];
 const primaryDeadline=deadlineEvents[0];
 const enteringCount=Object.values(plans).filter(plan=>plan.decision==="Entering").length;
 const pastEvents=eventCatalogue.filter(event=>event.end<today);
 const pastYears=Array.from(new Set(pastEvents.map(event=>event.end.slice(0,4)))).sort().reverse();
 const archivedThisMonth=pastEvents.filter(event=>event.end.slice(0,7)===today.slice(0,7)).length;
 const verifiedDateCount=eventCatalogue.filter(event=>dateStatus(event)!=="Provisional").length;
 const dateReviewCount=eventCatalogue.length-verifiedDateCount;
 const completeResultsCount=pastEvents.filter(event=>resultStatus(event,today)==="Complete").length;
 const missingResultsCount=pastEvents.filter(event=>["Missing","Partial"].includes(resultStatus(event,today))).length;
 const myCurrentEvents=currentEvents.filter(isMyEvent);
 const actionEvents=currentEvents.filter(needsAction);
 const linkedAthleteNames=(id:string)=>{const link=teamLinks[id];if(!link)return plans[id]?.athletes??[];return link.athleteIds.map(athleteId=>clubAthletes.find(athlete=>athlete.id===athleteId)?.name).filter(Boolean) as string[]};
 const linkedPlans=Object.fromEntries(eventCatalogue.flatMap(event=>plans[event.id]||teamLinks[event.id]?.athleteIds.length?[[event.id,{...emptyPlan,...plans[event.id],athletes:linkedAthleteNames(event.id)}]]:[])) as Plans;
 const updatePlan=(id:string,change:Partial<EventPlan>)=>setPlans(current=>({...current,[id]:{...emptyPlan,...current[id],...change}}));
 const updateTeam=(eventId:string,athlete:ClubAthlete)=>setTeamLinks(current=>{const existing=current[eventId]??{athleteIds:[],athleteNames:[],updatedAt:""};const selected=existing.athleteIds.includes(athlete.id);const athleteIds=selected?existing.athleteIds.filter(id=>id!==athlete.id):[...existing.athleteIds,athlete.id];const athleteNames=athleteIds.map(id=>clubAthletes.find(item=>item.id===id)?.name).filter(Boolean) as string[];updatePlan(eventId,{athletes:athleteNames});return{...current,[eventId]:{athleteIds,athleteNames,updatedAt:new Date().toISOString()}}});
 const toggleTrack=(id:string)=>setTracked(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);
 const openEvent=(event:EventRecord)=>{setSelected(event);setDetailTab("Overview")};
 const toggleCompare=(id:string)=>setCompareIds(current=>current.includes(id)?current.filter(item=>item!==id):current.length<3?[...current,id]:(notice("Compare up to three events at once"),current));
 const exportCalendar=()=>{if(!visible.length)return;const url=URL.createObjectURL(new Blob([calendarContent(visible)],{type:"text/calendar"}));const link=document.createElement("a");link.href=url;link.download=`fighteye-${period==="Current events"?"current":"past"}-events.ics`;link.click();URL.revokeObjectURL(url);notice(`${visible.length} event${visible.length===1?"":"s"} added to the FightEye calendar file`)};
 const reset=()=>{setQuery("");setOrg("All organisers");setLevel("All levels");setContinent("All continents");setCountry("All countries");setMonth("All dates");setPastYear("All years");setResultFilter("All results");setCurrentFilter("All current");setDateRange("All time");setEventView("All events");setTrackedOnly(false);setClubOnly(false);setIntegrityFilter("All events")};

 return <>
  <section className="events-home-head panel"><div className="events-home-title"><span className="badge gold">EVENTS</span><div><h2>Event timeline</h2><p>Plan entries, follow live competitions and review past results.</p></div><span className="events-catalogue-state">✓ Checked {catalogueVerifiedAt}</span></div><div className="events-home-actions">{primaryEvent?<button onClick={()=>openEvent(primaryEvent)}><small>{eventIsLive(primaryEvent,today)?"LIVE NOW":"NEXT EVENT"}</small><b>{primaryEvent.name}</b><span>{dateLabel(primaryEvent.start,primaryEvent.end)} · {primaryEvent.city}</span></button>:<article><small>NEXT EVENT</small><b>No upcoming event</b><span>Check the past-events archive</span></article>}{primaryDeadline?<button className={daysUntil(primaryDeadline.closing!,today)<=14?"urgent":""} onClick={()=>openEvent(primaryDeadline)}><small>NEXT ENTRY DEADLINE</small><b>{primaryDeadline.name}</b><span>{daysUntil(primaryDeadline.closing!,today)===0?"Closes today":daysUntil(primaryDeadline.closing!,today)===1?"Closes tomorrow":`Closes in ${daysUntil(primaryDeadline.closing!,today)} days`}</span></button>:<article><small>ENTRY DEADLINES</small><b>Nothing due</b><span>No current closing date</span></article>}</div></section>
  <nav className="event-period-tabs timeline-period-tabs panel" role="tablist" aria-label="Current and past events"><button role="tab" aria-selected={period==="Current events"} className={period==="Current events"?"active":""} onClick={()=>{setPeriod("Current events");setCurrentFilter("All current");setDateRange("All time");setEventView("All events");setMonth("All dates");setResultFilter("All results");setIntegrityFilter("All events")}}><span><b>Current events</b><small>Live and upcoming</small></span><em>{currentEvents.length}</em></button><button role="tab" aria-selected={period==="Past events"} className={period==="Past events"?"active":""} onClick={()=>{setPeriod("Past events");setMonth("All dates");setPastYear("All years");setDateRange("All time");setEventView("All events");setResultFilter("All results");setTrackedOnly(false);setIntegrityFilter("All events")}}><span><b>Past events</b><small>Finished and results</small></span><em>{pastEvents.length}</em></button></nav>
  <section className="planner-toolbar panel"><label className="planner-search">⌕<input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search events…"/></label><button className="planner-filter-toggle" aria-expanded={filtersOpen} onClick={()=>setFiltersOpen(value=>!value)}>Filters <b>{[org!=="All organisers",level!=="All levels",continent!=="All continents",country!=="All countries",month!=="All dates",dateRange!=="All time",clubOnly,trackedOnly].filter(Boolean).length}</b></button>{filtersOpen&&<div className="planner-filter-fields"><label className="filter-labelled">Continent<select value={continent} onChange={event=>{setContinent(event.target.value);setCountry("All countries")}}><option>All continents</option>{continents.map(item=><option key={item}>{item}</option>)}</select></label><label className="filter-labelled">Country<select value={country} onChange={event=>setCountry(event.target.value)}><option>All countries</option>{countries.map(item=><option key={item}>{item}</option>)}</select></label><select aria-label="Organiser" value={org} onChange={event=>setOrg(event.target.value)}>{organisers.map(item=><option key={item}>{item}</option>)}</select><select aria-label="Level" value={level} onChange={event=>setLevel(event.target.value)}>{["All levels","UK","Europe","World","USA"].map(item=><option key={item}>{item}</option>)}</select>{period==="Current events"&&<select aria-label="Month" value={month} onChange={event=>setMonth(event.target.value)}>{months.map(item=><option key={item}>{item}</option>)}</select>}<button className={clubOnly?"active":""} onClick={()=>setClubOnly(value=>!value)}>My club teams</button><button className={trackedOnly?"active":""} onClick={()=>setTrackedOnly(value=>!value)}>Tracked</button><nav className="timeline-range-filters" aria-label="Filter events by date range">{(["All time","30 days","90 days","12 months"] as DateRange[]).map(item=><button className={dateRange===item?"active":""} aria-pressed={dateRange===item} onClick={()=>{setDateRange(item);setMonth("All dates");setPastYear("All years")}} key={item}>{item==="All time"?(period==="Current events"?"All current":"All history"):period==="Current events"?`Next ${item}`:`Last ${item}`}</button>)}</nav><button onClick={reset}>Reset filters</button></div>}</section>
  {period==="Current events"&&<nav className="current-event-filters panel" aria-label="Filter current events by status">{(["All current","Live now","Registration open","Closing soon","Upcoming","Dates to review"] as CurrentFilter[]).map(item=>{const count=item==="All current"?currentEvents.length:item==="Live now"?liveEvents.length:item==="Registration open"?registrationOpenEvents.length:item==="Closing soon"?closingSoonEvents.length:item==="Upcoming"?futureEvents.length:currentEvents.filter(event=>dateStatus(event)==="Provisional").length;return <button className={currentFilter===item?"active":""} aria-pressed={currentFilter===item} onClick={()=>{setCurrentFilter(item);setMonth("All dates");if(item==="Dates to review")setIntegrityFilter("All events")}} key={item}><span>{item}</span><b>{count}</b></button>})}</nav>}
  {period==="Current events"&&<nav className="timeline-personal-filters panel" aria-label="Personal event timeline"><span><small>PHASE 122</small><b>My timeline</b></span>{(["All events","My events","Needs action"] as EventView[]).map(item=>{const count=item==="All events"?currentEvents.length:item==="My events"?myCurrentEvents.length:actionEvents.length;return <button className={eventView===item?"active":""} aria-pressed={eventView===item} onClick={()=>{setEventView(item);setMonth("All dates")}} key={item}>{item}<b>{count}</b></button>})}</nav>}
  {period==="Past events"&&<section className="past-events-head panel"><div><span className="badge gold">PHASE 108 · PAST EVENTS ARCHIVE</span><h3>Results, records and previous competitions</h3><p>Newest completed events appear first. Registration actions are replaced by results links.</p></div><div><select aria-label="Past event year" value={pastYear} onChange={event=>setPastYear(event.target.value)}><option>All years</option>{pastYears.map(year=><option key={year}>{year}</option>)}</select><select aria-label="Past event results status" value={resultFilter} onChange={event=>setResultFilter(event.target.value as ResultFilter)}>{["All results","Complete","Partial","Missing"].map(item=><option key={item}>{item}</option>)}</select></div></section>}
  {(continent!=="All continents"||country!=="All countries"||org!=="All organisers"||level!=="All levels"||query.trim())&&<div className="active-event-filters" aria-label="Active event filters"><span>Showing</span>{continent!=="All continents"&&<button onClick={()=>{setContinent("All continents");setCountry("All countries")}} aria-label={`Remove continent filter: ${continent}`}>{continent} ×</button>}{country!=="All countries"&&<button onClick={()=>setCountry("All countries")} aria-label={`Remove country filter: ${country}`}>{country} ×</button>}{org!=="All organisers"&&<button onClick={()=>setOrg("All organisers")} aria-label={`Remove organiser filter: ${org}`}>{org} ×</button>}{level!=="All levels"&&<button onClick={()=>setLevel("All levels")} aria-label={`Remove level filter: ${level}`}>{level} ×</button>}{query.trim()&&<button onClick={()=>setQuery("")} aria-label="Clear event search">Search: {query.trim()} ×</button>}<button className="clear-all" onClick={reset}>Clear all</button></div>}
  <div className="planner-result-head"><span role="status" aria-live="polite"><b>{visible.length}</b> {period.toLowerCase()}</span><div className="timeline-result-actions"><button className="calendar-pack" onClick={exportCalendar} disabled={!visible.length}>＋ Calendar</button><div className="event-layout-switch" role="group" aria-label="Event display"><button className={layout==="Timeline"?"active":""} onClick={()=>setLayout("Timeline")}>◷ Timeline</button><button className={layout==="Agenda"?"active":""} onClick={()=>setLayout("Agenda")}>☷ Agenda</button><button className={layout==="Cards"?"active":""} onClick={()=>setLayout("Cards")}>▦ Cards</button></div></div></div>
  {compareIds.length>0&&<EventComparison
   events={compareIds.map(id=>eventCatalogue.find(event=>event.id===id)).filter(Boolean) as EventRecord[]}
   plans={linkedPlans}
   today={today}
   onOpen={openEvent}
   onRemove={toggleCompare}
   onClear={()=>setCompareIds([])}
  />}
  {visible.length===0?<section className="panel discovery-empty"><b>No events found in this view.</b><p>Try a wider date range or clear the filters.</p><button onClick={reset}>Show all events</button></section>:layout==="Timeline"?<EventTimeline events={displayedEvents} months={timelineMonths} monthCounts={timelineMonthCounts} selectedMonth={month} today={today} plans={linkedPlans} operations={teamOperations} teamLinks={teamLinks} tracked={tracked} compared={compareIds} organisation={organisation} clashes={clashesByEvent} onMonth={setMonth} onTrack={toggleTrack} onCompare={toggleCompare} onOpen={openEvent} onLive={openLiveEvent} period={period}/>:layout==="Agenda"?<EventAgenda events={displayedEvents} today={today} plans={linkedPlans} clashes={clashesByEvent} onOpen={openEvent} onLive={openLiveEvent} period={period}/>:<section className="planner-card-grid">{displayedEvents.map(event=><EventCard key={event.id} event={event} today={today} plan={linkedPlans[event.id]} tracked={tracked.includes(event.id)} compared={compareIds.includes(event.id)} onTrack={()=>toggleTrack(event.id)} onCompare={()=>toggleCompare(event.id)} onOpen={()=>openEvent(event)}/>)}</section>}
  {visibleLimit<visible.length&&<button className="event-load-more" onClick={()=>setVisibleLimit(limit=>limit+12)}>Show 12 more events <small>{visible.length-visibleLimit} remaining</small></button>}
  <details className="timeline-support panel"><summary><span><b>Catalogue health and source audit</b><small>Dates, sources, results coverage and archive rules</small></span><em>Review</em></summary><div>
  <section className="event-directory panel"><div><span className="eyebrow">PHASE 106 · COMPREHENSIVE DIRECTORY</span><h3>{eventCatalogue.length} competitions across {new Set(eventCatalogue.map(event=>event.org)).size} organisers</h3><p>WAKO, UK circuits, international championships and recognised open-event platforms are combined in one searchable directory.</p></div><div className="directory-sources" aria-label="Event sources">{catalogueSources.map(source=><span key={source}>{source}</span>)}</div></section>
  <section className="archive-rule panel"><i>↻</i><div><span className="eyebrow">PHASE 107 · AUTOMATIC EVENT LIFECYCLE</span><h3>Finished events move themselves</h3><p>An event stays in Current Events through its inclusive end date. On the following UK calendar day, it moves to Past Events automatically.</p></div><strong><b>{archivedThisMonth}</b><small>moved this month</small></strong></section>
  <section className="integrity-command panel" aria-label="Timeline integrity centre"><header><div><span className="eyebrow">PHASE 100 · DATE AUDIT</span><h3>Timeline integrity centre</h3><p>Official confirmation is separated from dates that still need organiser review.</p></div><span className="integrity-checked">Checked {catalogueVerifiedAt}</span></header><div className="integrity-grid"><button className={integrityFilter==="All events"?"active":""} onClick={()=>setIntegrityFilter("All events")}><small>PHASE 100</small><b>{verifiedDateCount}</b><span>verified or corrected dates</span></button><button className={integrityFilter==="Dates to review"?"active warning":"warning"} onClick={()=>setIntegrityFilter("Dates to review")}><small>PHASE 101</small><b>{dateReviewCount}</b><span>dates to review</span></button><button className={integrityFilter==="Missing results"?"active alert":"alert"} onClick={()=>{setIntegrityFilter("Missing results");setPeriod("Past events");setEventView("All events");setMonth("All dates")}}><small>PHASE 102</small><b>{missingResultsCount}</b><span>missing or partial results</span></button><article><small>OFFICIAL RESULTS</small><b>{completeResultsCount}/{pastEvents.length}</b><span>completed event records linked</span></article></div></section>
  <section className="planner-kpis"><article><small>Tracked</small><b>{tracked.length}</b><span>Saved on this device</span></article><article><small>Entering</small><b>{enteringCount}</b><span>Club attendance planned</span></article><article><small>Date status</small><b>{verifiedDateCount}</b><span>Verified or corrected</span></article><article><small>Countries</small><b>{new Set(currentEvents.map(event=>event.country)).size}</b><span>UK and international</span></article></section>
  </div></details>
  {selected&&<EventPlannerDrawer
   event={selected}
   clubAthletes={clubAthletes}
   today={today}
   tab={detailTab}
   setTab={setDetailTab}
   plan={{...emptyPlan,...linkedPlans[selected.id]}}
   update={change=>updatePlan(selected.id,change)}
   updateTeam={athlete=>updateTeam(selected.id,athlete)}
   tracked={tracked.includes(selected.id)}
   onTrack={()=>toggleTrack(selected.id)}
   onClose={()=>setSelected(null)}
   notice={notice}
   onLive={()=>openLiveEvent(selected)}
  />}
 </>;
}

function EventTimeline({events,months,monthCounts,selectedMonth,today,plans,operations,teamLinks,tracked,compared,organisation,clashes,onMonth,onTrack,onCompare,onOpen,onLive,period}:{events:EventRecord[];months:string[];monthCounts:Record<string,number>;selectedMonth:string;today:string;plans:Plans;operations:EventTeamOperations;teamLinks:EventTeamLinks;tracked:string[];compared:string[];organisation:OrganisationBrand;clashes:Record<string,string[]>;onMonth:(month:string)=>void;onTrack:(id:string)=>void;onCompare:(id:string)=>void;onOpen:(event:EventRecord)=>void;onLive:(event:EventRecord)=>void;period:Period}){
 const nextEvent=period==="Past events"?events[0]:events.find(event=>event.end>=today)??events[0];
 const nextDeadline=events.filter(event=>event.closing&&event.closing>=today).sort((a,b)=>(a.closing??"").localeCompare(b.closing??""))[0];
 return <section className="event-timeline panel" aria-label={`${period} event timeline`}><header><div className="timeline-brand-row"><OrganisationMark brand={organisation} compact/><span className="badge gold">PHASE 111 · ORGANISATION IDENTITY</span></div><div className="timeline-heading"><div><span className="eyebrow">{period==="Past events"?"RESULTS ARCHIVE":"PHASE 109 · SMART EVENT TIMELINE · PHASES 116–120 CURRENT / PAST"}</span><h3>{period}</h3><p>{period==="Past events"?"Completed competitions, result status and official records in reverse date order.":"Dates, deadlines, athlete availability and coach cover in one clear sequence."}</p></div>{nextEvent&&<button onClick={()=>onOpen(nextEvent)}>{period==="Past events"?"Open latest event →":"Open next event →"}</button>}</div>{period==="Current events"&&<div className="timeline-glance"><article><small>NEXT EVENT</small><b>{nextEvent.name}</b><span>{dateLabel(nextEvent.start,nextEvent.end)} · {daysUntil(nextEvent.start,today)<=0?"Under way":`in ${daysUntil(nextEvent.start,today)} days`}</span></article><article><small>NEXT ENTRY DEADLINE</small><b>{nextDeadline?.name??"No deadline listed"}</b><span>{nextDeadline?.closing?`${dateLabel(nextDeadline.closing,nextDeadline.closing)} · ${daysUntil(nextDeadline.closing,today)} days left`:"Check the organiser source"}</span></article></div>}{period==="Current events"&&months.length>1&&<nav className="timeline-months" aria-label="Filter timeline by month"><button className={selectedMonth==="All dates"?"active":""} onClick={()=>onMonth("All dates")}>All <b>{Object.values(monthCounts).reduce((sum,count)=>sum+count,0)}</b></button>{months.map(item=><button className={selectedMonth===item?"active":""} onClick={()=>onMonth(item)} key={item}>{item.replace(" 2026","").replace(" 2027","")} <b>{monthCounts[item]}</b></button>)}</nav>}</header><div className="event-timeline-list">{events.map((event,index)=>{const newMonth=index===0||monthLabel(events[index-1].start)!==monthLabel(event.start);return <Fragment key={event.id}>{newMonth&&<div className="timeline-month-break"><span>{monthLabel(event.start)}</span><i>{events.filter(item=>monthLabel(item.start)===monthLabel(event.start)).length} events</i></div>}<TimelineEvent event={event} index={index} today={today} plan={plans[event.id]} operation={operations[event.id]} linkedCount={teamLinks[event.id]?.athleteIds.length??0} conflicts={clashes[event.id]??[]} tracked={tracked.includes(event.id)} compared={compared.includes(event.id)} onTrack={()=>onTrack(event.id)} onCompare={()=>onCompare(event.id)} onOpen={()=>onOpen(event)} onLive={()=>onLive(event)}/></Fragment>})}</div></section>;
}

function TimelineEvent({event,index,today,plan,operation,linkedCount,conflicts,tracked,compared,onTrack,onCompare,onOpen,onLive}:{event:EventRecord;index:number;today:string;plan?:EventPlan;operation?:EventTeamOperation;linkedCount:number;conflicts:string[];tracked:boolean;compared:boolean;onTrack:()=>void;onCompare:()=>void;onOpen:()=>void;onLive:()=>void}){
 const state=eventState(event,today);const until=daysUntil(event.start,today);const parts=dateParts(event.start);const deadline=event.closing?daysUntil(event.closing,today):null;const readiness=plan?Math.round(plan.checks.length/registrationChecks.length*100):0;const confirmed=operation?Object.values(operation.availability).filter(value=>value==="Confirmed").length:0;const unavailable=operation?Object.values(operation.availability).filter(value=>value==="Unavailable").length:0;const teamReadiness=linkedCount?Math.round(confirmed/linkedCount*75+(operation?.coachIds.length?25:0)):0;const dateState=dateStatus(event);const resultState=resultStatus(event,today);const isPast=event.end<today;
 return <article className="event-timeline-row"><div className="timeline-marker"><i>{index+1}</i><span/></div><time dateTime={event.start}><span className="timeline-date-tile"><small>{parts.weekday}</small><b>{parts.day}</b><em>{parts.month}</em></span><span className="timeline-date-copy"><b>{dateLabel(event.start,event.end)}</b><small>{event.flag} {event.city}, {event.country}</small>{until>=0&&<em>{until===0?"Starts today":until===1?"Tomorrow":`In ${until} days`}</em>}</span></time><div className="timeline-event"><div className="timeline-event-flags"><span className={`source-state ${statusClass(dateState)}`}>{dateState==="Verified"?"✓ Verified":dateState==="Corrected"?"↻ Corrected":"! Provisional date"}</span><span className={`event-status ${statusClass(state)}`}>{state}</span>{conflicts.length>0&&!isPast&&<span className="timeline-clash-chip" title={`Overlaps ${conflicts.join(", ")}`}>↔ {conflicts.length} overlap{conflicts.length===1?"":"s"}</span>}{isPast&&<span className={`result-state ${statusClass(resultState)}`}>{resultState==="Complete"?"✓ Results complete":resultState==="Partial"?"◐ Partial results":"! Results missing"}</span>}</div><h3>{event.name}</h3><p>{event.org} · {event.level}</p><dl className="timeline-details"><div><dt>Venue</dt><dd>{event.venue}</dd></div><div><dt>Type</dt><dd>{event.collections[0]}</dd></div></dl>{event.dateNote&&<p className="timeline-audit-note">{event.dateNote}</p>}<div className="event-disciplines">{event.disciplines.map(item=><span key={item}>{item}</span>)}</div>{event.closing&&!isPast&&<small className={`timeline-deadline ${deadline!==null&&deadline>=0&&deadline<=7?"urgent":deadline!==null&&deadline>=0&&deadline<=14?"soon":""}`}>{deadline!==null&&deadline<0?"Entries closed":deadline===0?"Entries close today":deadline===1?"Entries close tomorrow":deadline!==null?`Entries close in ${deadline} days`:"Entry date"} · {dateLabel(event.closing,event.closing)}</small>}{plan&&!isPast&&<div className="timeline-plan"><span><b>{plan.athletes.length}</b> linked athletes</span><span><b>{plan.checks.length}/{registrationChecks.length}</b> ready</span><i aria-label={`${readiness}% registration ready`}><em style={{width:`${readiness}%`}}/></i></div>}{plan?.athletes.length?<div className="timeline-team" aria-label={`${plan.athletes.length} linked club athletes`}><small>CLUB TEAM</small>{plan.athletes.slice(0,3).map(name=><span key={name}><i>{name.split(" ").map(part=>part[0]).join("").slice(0,2)}</i>{name}</span>)}{plan.athletes.length>3&&<b>+${plan.athletes.length-3}</b>}</div>:null}{linkedCount>0&&!isPast&&<div className="timeline-team-readiness"><div><span>TEAM READY</span><b>{teamReadiness}%</b></div><i aria-label={`${teamReadiness}% event team ready`}><em style={{width:`${teamReadiness}%`}}/></i><small>{confirmed}/{linkedCount} confirmed · {operation?.coachIds.length??0} coach{(operation?.coachIds.length??0)===1?"":"es"}{unavailable?` · ${unavailable} unavailable`:""}</small></div>}</div><div className="timeline-actions">{plan&&!isPast&&<span className={`club-decision ${statusClass(plan.decision)}`}>{plan.decision}</span>}<button className={tracked?"tracked":""} onClick={onTrack}>{tracked?"★ Tracked":"☆ Track"}</button><button className={compared?"compare active":"compare"} onClick={onCompare}>{compared?"✓ Comparing":"＋ Compare"}</button><button className="timeline-details-button" onClick={onOpen}>Event details</button>{isPast?<a className={`timeline-results ${statusClass(resultState)}`} href={event.resultsUrl??event.sourceUrl} target="_blank" rel="noreferrer" aria-label={`${resultState==="Complete"?"View":"Check"} results for ${event.name}`}>{resultState==="Complete"?"View results ↗":"Check results ↗"}</a>:eventIsLive(event,today)?<button className="timeline-live" onClick={onLive}>Open live tracker</button>:state==="Registration open"?<a className="timeline-register" href={event.registrationUrl} target="_blank" rel="noreferrer" aria-label={`Register for ${event.name}`}>Register now ↗</a>:<button className="timeline-register" onClick={onOpen}>Prepare event</button>}</div></article>;
}

function EventAgenda({events,today,plans,clashes,onOpen,onLive,period}:{events:EventRecord[];today:string;plans:Plans;clashes:Record<string,string[]>;onOpen:(event:EventRecord)=>void;onLive:(event:EventRecord)=>void;period:Period}){
 const groupFor=(event:EventRecord)=>{if(period==="Past events")return monthLabel(event.start);if(eventIsLive(event,today))return"Live now";const days=daysUntil(event.start,today);return days<=7?"Next 7 days":days<=30?"Next 30 days":"Later"};
 return <section className="event-agenda panel" aria-label="Compact event agenda"><header><div><span className="badge gold">PHASE 121 · GROUPED IPHONE AGENDA</span><h3>Events in date-sized groups</h3></div><small>{events.length} event{events.length===1?"":"s"}</small></header>{events.map((event,index)=>{const state=eventState(event,today);const isPast=eventBelongsInPast(event,today);const parts=dateParts(event.start);const plan=plans[event.id];const group=groupFor(event);const newGroup=index===0||groupFor(events[index-1])!==group;return <Fragment key={event.id}>{newGroup&&<div className="agenda-group"><b>{group}</b><span>{events.filter(item=>groupFor(item)===group).length}</span></div>}<article><time dateTime={event.start}><b>{parts.day}</b><span>{parts.month}<small>{parts.weekday}</small></span></time><div><span className="agenda-flags"><i className={statusClass(state)}>{state}</i>{clashes[event.id]?.length>0&&<i className="clash">↔ {clashes[event.id].length} overlap{clashes[event.id].length===1?"":"s"}</i>}</span><h3>{event.name}</h3><p>{event.flag} {event.city} · {event.org}</p>{plan?.athletes.length?<small>{plan.athletes.length} club athlete{plan.athletes.length===1?"":"s"} linked</small>:null}</div><nav><button onClick={()=>onOpen(event)}>Details</button><a href={directionsUrl(event)} target="_blank" rel="noreferrer">⌖ Route</a>{!isPast&&<button className="live" onClick={()=>onLive(event)}>● Live</button>}{isPast&&<a href={event.resultsUrl??event.sourceUrl} target="_blank" rel="noreferrer">Results ↗</a>}</nav></article></Fragment>})}</section>
}

function EventCard({event,today,plan,tracked,compared,onTrack,onCompare,onOpen}:{event:EventRecord;today:string;plan?:EventPlan;tracked:boolean;compared:boolean;onTrack:()=>void;onCompare:()=>void;onOpen:()=>void}){
 const state=eventState(event,today);const isPast=event.end<today;const resultState=resultStatus(event,today);
 return <article className="planner-event-card"><div className="planner-card-head"><span>{event.flag} {event.level}</span><div><button className={compared?"compared":""} onClick={onCompare} aria-label={`${compared?"Remove from":"Add to"} event comparison`}>⇄</button><button className={tracked?"tracked":""} onClick={onTrack} aria-label={`${tracked?"Stop tracking":"Track"} ${event.name}`}>{tracked?"★":"☆"}</button></div></div><time>{dateLabel(event.start,event.end)}</time><small>{event.org} · {dateStatus(event)} date</small><h3>{event.name}</h3><p>{event.city}, {event.country}</p><div className="event-disciplines">{event.disciplines.map(item=><span key={item}>{item}</span>)}</div><div className="planner-card-status"><span className={`event-status ${statusClass(state)}`}>{state}</span>{isPast?<span className={`result-state ${statusClass(resultState)}`}>{resultState} results</span>:plan&&<b>{plan.decision}</b>}</div><button className="planner-open" onClick={onOpen}>Open event details →</button></article>;
}

function EventComparison({events,plans,today,onOpen,onRemove,onClear}:{events:EventRecord[];plans:Plans;today:string;onOpen:(event:EventRecord)=>void;onRemove:(id:string)=>void;onClear:()=>void}){
 return <section className="event-comparison panel"><header><div><span className="badge gold">PHASE 92 · COMPARE EVENTS</span><h3>{events.length===1?"Choose one or two more events":`${events.length} events side by side`}</h3></div><button onClick={onClear}>Clear</button></header><div>{events.map(event=>{const plan={...emptyPlan,...plans[event.id]};return <article key={event.id}><button className="comparison-remove" onClick={()=>onRemove(event.id)} aria-label={`Remove ${event.name} from comparison`}>×</button><span>{event.flag} {event.level}</span><h3>{event.name}</h3><time>{dateLabel(event.start,event.end)}</time><dl><div><dt>Location</dt><dd>{event.city}</dd></div><div><dt>Status</dt><dd>{eventState(event,today)}</dd></div><div><dt>Club plan</dt><dd>{plans[event.id]?plan.decision:"Not planned"}</dd></div><div><dt>Athletes</dt><dd>{plan.athletes.length}</dd></div></dl><button className="primary" onClick={()=>onOpen(event)}>Open details</button></article>})}</div></section>;
}

function EventPlannerDrawer({event,clubAthletes,today,tab,setTab,plan,update,updateTeam,tracked,onTrack,onClose,notice,onLive}:{event:EventRecord;clubAthletes:ClubAthlete[];today:string;tab:"Overview"|"Club plan"|"Entries";setTab:(tab:"Overview"|"Club plan"|"Entries")=>void;plan:EventPlan;update:(change:Partial<EventPlan>)=>void;updateTeam:(athlete:ClubAthlete)=>void;tracked:boolean;onTrack:()=>void;onClose:()=>void;notice:(message:string)=>void;onLive:()=>void}){
 const state=eventState(event,today);const isPast=event.end<today;const dateState=dateStatus(event);const resultState=resultStatus(event,today);
 const toggleCheck=(id:string)=>update({checks:plan.checks.includes(id)?plan.checks.filter(item=>item!==id):[...plan.checks,id]});
 const addToCalendar=()=>{const url=URL.createObjectURL(new Blob([calendarContent([event])],{type:"text/calendar"}));const link=document.createElement("a");link.href=url;link.download=`${event.id}.ics`;link.click();URL.revokeObjectURL(url);notice(`${event.name} calendar file created`)};
 const share=async()=>{const text=`${event.name} · ${dateLabel(event.start,event.end)} · ${event.city}, ${event.country} · ${event.registrationUrl}`;try{if(navigator.share)await navigator.share({title:event.name,text});else{await navigator.clipboard.writeText(text);notice("Event details copied")}}catch(error){if(error instanceof DOMException&&error.name==="AbortError")return;notice("Could not share event")}};
 const downloadBrief=()=>{const completed=registrationChecks.filter(check=>plan.checks.includes(check.id)).map(check=>`✓ ${check.label}`);const outstanding=registrationChecks.filter(check=>!plan.checks.includes(check.id)).map(check=>`○ ${check.label}`);const brief=["FIGHTEYE CLUB EVENT BRIEF",event.name,dateLabel(event.start,event.end),`${event.venue}, ${event.city}, ${event.country}`,`Organiser: ${event.org}`,`Club decision: ${plan.decision}`,`Registration closes: ${event.closing?dateLabel(event.closing,event.closing):"Check organiser"}`,"",`ATHLETES (${plan.athletes.length})`,...(plan.athletes.length?plan.athletes.map(name=>`• ${name}`):["No athletes linked"]),"","READINESS",...completed,...outstanding,"",`Travel: ${plan.travel||"Not recorded"}`,`Hotel: ${plan.hotel||"Not recorded"}`,`Budget: ${plan.budget?`£${plan.budget}`:"Not recorded"}`,`Notes: ${plan.notes||"None"}`,"",`Registration: ${event.registrationUrl}`,`Directions: ${directionsUrl(event)}`].join("\n");const url=URL.createObjectURL(new Blob([brief],{type:"text/plain"}));const link=document.createElement("a");link.href=url;link.download=`${event.id}-club-brief.txt`;link.click();URL.revokeObjectURL(url);notice(`${event.name} club briefing downloaded`)};
 return <div className="event-drawer-backdrop" onMouseDown={action=>{if(action.target===action.currentTarget)onClose()}}><aside className="event-drawer" role="dialog" aria-modal="true" aria-label={`${event.name} planner`}><header><button className="drawer-close" onClick={onClose} aria-label="Close event planner">×</button><span className={`source-state ${statusClass(dateState)}`}>{dateState==="Verified"?"✓ Date verified":dateState==="Corrected"?"↻ Date corrected":"! Date provisional"}</span><h2>{event.flag} {event.name}</h2><p>{dateLabel(event.start,event.end)} · {event.city}, {event.country}</p><div><span className={`event-status ${statusClass(state)}`}>{state}</span>{isPast&&<span className={`result-state ${statusClass(resultState)}`}>{resultState} results</span>}<button className={tracked?"tracked":""} onClick={onTrack}>{tracked?"★ Tracked":"☆ Track event"}</button></div></header><nav role="tablist" aria-label="Event planner sections">{(["Overview",...(!isPast?["Club plan","Entries"]:[])] as ("Overview"|"Club plan"|"Entries")[]).map(item=><button role="tab" aria-selected={tab===item} className={tab===item?"active":""} onClick={()=>setTab(item)} key={item}>{item}{item==="Entries"&&plan.athletes.length>0?<b>{plan.athletes.length}</b>:null}</button>)}</nav><div className="drawer-content">{tab==="Overview"&&<section className="event-overview"><div className="event-facts">{[["Venue",event.venue],["Organiser",event.org],["Date status",dateState],[isPast?"Results":"Entry date",isPast?`${resultState} results`:event.closing?dateLabel(event.closing,event.closing):"Check source"]].map(([label,value])=><dl key={label}><dt>{label}</dt><dd>{value}</dd></dl>)}</div>{event.dateNote&&<article className="drawer-audit-note"><span className="eyebrow">AUDIT NOTE</span><p>{event.dateNote}</p></article>}<article><span className="eyebrow">DISCIPLINES</span><div className="event-disciplines">{event.disciplines.map(item=><span key={item}>{item}</span>)}</div></article><article><span className="eyebrow">COLLECTIONS</span><div className="event-collections">{event.collections.map(item=><span key={item}>{item}</span>)}</div></article><article className="event-provenance"><span className="eyebrow">EVENT SOURCE</span><dl><div><dt>Date</dt><dd>{dateState}{dateState==="Provisional"?" · confirm with organiser":""}</dd></div><div><dt>Results</dt><dd>{resultState}{resultState==="Missing"&&isPast?" · check organiser":""}</dd></div><div><dt>Catalogue review</dt><dd>{catalogueVerifiedAt}</dd></div></dl><p>Organiser information can change after the catalogue review. Check the source before booking or entering.</p></article><div className="source-actions"><a href={event.sourceUrl} target="_blank" rel="noreferrer">Open {event.sourceName} source ↗</a><a href={directionsUrl(event)} target="_blank" rel="noreferrer">⌖ Venue directions ↗</a>{isPast?<a className={resultState==="Complete"?"primary":""} href={event.resultsUrl??event.sourceUrl} target="_blank" rel="noreferrer">{resultState==="Complete"?"View official results ↗":"Check for results ↗"}</a>:<><button className="live-event-launch" onClick={onLive}>● Open live tracker</button><a className="primary" href={event.registrationUrl} target="_blank" rel="noreferrer">Open registration ↗</a></>}</div><section className="event-portability"><span className="badge gold">PHASE 103 · LIVE EVENT BRIDGE · PHASES 125–126 · MOBILE EVENT PACK</span><h3>{isPast?"Results and sharing":"Directions and club briefing"}</h3><p>{isPast?"Share the event record while keeping missing or partial results visible.":"Open the venue route or download the saved club plan, athlete list and readiness checks."}</p><div>{!isPast&&<button onClick={addToCalendar}>＋ Add to calendar</button>}<button onClick={share}>↗ Share event</button>{!isPast&&<button onClick={downloadBrief}>⇩ Club briefing</button>}</div></section></section>}{tab==="Club plan"&&<section className="club-plan"><label>Club decision<select value={plan.decision} onChange={action=>update({decision:action.target.value as Decision})}>{["Watching","Considering","Entering","Not attending"].map(item=><option key={item}>{item}</option>)}</select></label><div className="plan-pair"><label>Travel plan<input value={plan.travel} onChange={action=>update({travel:action.target.value})} placeholder="Cars, minibus or flights"/></label><label>Hotel<input value={plan.hotel} onChange={action=>update({hotel:action.target.value})} placeholder="Hotel or day trip"/></label></div><label>Working budget (£)<input inputMode="decimal" value={plan.budget} onChange={action=>update({budget:action.target.value})} placeholder="0"/></label><label>Planning notes<textarea value={plan.notes} onChange={action=>update({notes:action.target.value})} placeholder="Deadlines, coaching cover, weigh-in or equipment notes"/></label><button className="primary" onClick={()=>notice(`${event.name} club plan saved`)}>Save club plan</button></section>}{tab==="Entries"&&<section className="event-entries"><div><span className="eyebrow">PHASE 105 · ATHLETE–CLUB LINK</span><h3>Select the club athletes to enter</h3><p>Stable athlete IDs keep the same team connected across the club roster and event timeline.</p></div>{clubAthletes.map(athlete=><button className={plan.athletes.includes(athlete.name)?"selected":""} onClick={()=>updateTeam(athlete)} key={athlete.id}><i>{plan.athletes.includes(athlete.name)?"✓":""}</i><span><b>{athlete.name}</b><small>{athlete.category} · {athlete.weight} · {athlete.disciplines.join(" / ")}</small></span></button>)}<section className="registration-readiness"><div><span className="badge gold">PHASE 91 · REGISTRATION READY</span><h3>{plan.checks.length}/{registrationChecks.length} checks complete</h3></div>{registrationChecks.map(check=><button className={plan.checks.includes(check.id)?"complete":""} onClick={()=>toggleCheck(check.id)} key={check.id}><i>{plan.checks.includes(check.id)?"✓":""}</i><span><b>{check.label}</b><small>{check.detail}</small></span></button>)}</section><div className="entry-footer"><span><b>{plan.athletes.length}</b> linked</span><a className={plan.athletes.length&&plan.checks.length===registrationChecks.length?"primary":"disabled"} href={plan.athletes.length&&plan.checks.length===registrationChecks.length?event.registrationUrl:undefined} target="_blank" rel="noreferrer">Continue to registration ↗</a></div></section>}</div></aside></div>;
}
